// src/components/WalletConnect.js
import React, { useState, useEffect, useCallback } from 'react';
import { BrowserProvider, formatEther } from 'ethers'; 
import detectEthereumProvider from '@metamask/detect-provider';

function WalletConnect({ onWalletConnected }) {
  const [account, setAccount] = useState(null);
  const [balance, setBalance] = useState(null);
  const [network, setNetwork] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [provider, setProvider] = useState(null);
  const [isMetaMaskInstalled, setIsMetaMaskInstalled] = useState(false);

  const NETWORKS = {
    '0x1': { name: 'Ethereum Mainnet', color: '#627EEA' },
    '0xaa36a7': { name: 'Sepolia Testnet', color: '#CFADFF' },
    '0x5': { name: 'Goerli Testnet', color: '#308DFF' },
    '0x89': { name: 'Polygon', color: '#8247E5' },
    '0x13881': { name: 'Mumbai', color: '#8247E5' },
    '0x539': { name: 'Local Hardhat', color: '#F39C12' }
  };

  // Hàm cập nhật thông tin ví (Dùng useCallback để tránh render vòng lặp)
  const updateWalletInfo = useCallback(async (newAccount, currentProvider) => {
    if (!newAccount || !currentProvider) {
      setAccount(null);
      setBalance(null);
      setNetwork(null);
      if (onWalletConnected) onWalletConnected(null);
      return;
    }

    try {
      const balanceBigInt = await currentProvider.getBalance(newAccount);
      const formattedBalance = formatEther(balanceBigInt);
      
      const networkInfo = await currentProvider.getNetwork();
      
      setAccount(newAccount);
      setBalance(formattedBalance);
      setNetwork(networkInfo);

      if (onWalletConnected) {
        onWalletConnected({
          account: newAccount,
          balance: formattedBalance,
          chainId: Number(networkInfo.chainId)
        });
      }
    } catch (err) {
      console.error("Lỗi cập nhật thông tin ví:", err);
    }
  }, [onWalletConnected]);

  // Khởi tạo Provider và lắng nghe sự kiện
  useEffect(() => {
    const init = async () => {
      const detectedProvider = await detectEthereumProvider();
      setIsMetaMaskInstalled(!!detectedProvider);

      if (detectedProvider) {
        const browserProvider = new BrowserProvider(detectedProvider);
        setProvider(browserProvider);

        // Kiểm tra kết nối ban đầu
        const accounts = await detectedProvider.request({ method: 'eth_accounts' });
        if (accounts.length > 0) {
          updateWalletInfo(accounts[0], browserProvider);
        }

        // LẮNG NGHE SỰ KIỆN THAY ĐỔI TÀI KHOẢN
        const handleAccountsChanged = (accounts) => {
          updateWalletInfo(accounts[0], browserProvider);
        };

        // LẮNG NGHE SỰ KIỆN THAY ĐỔI MẠNG
        const handleChainChanged = () => {
          // Khi đổi mạng, cách an toàn nhất là reload hoặc fetch lại toàn bộ
          window.location.reload();
        };

        detectedProvider.on('accountsChanged', handleAccountsChanged);
        detectedProvider.on('chainChanged', handleChainChanged);

        return () => {
          detectedProvider.removeListener('accountsChanged', handleAccountsChanged);
          detectedProvider.removeListener('chainChanged', handleChainChanged);
        };
      }
    };
    init();
  }, [updateWalletInfo]);

  const connectWallet = async () => {
    setError('');
    setLoading(true);
    try {
      if (!provider) throw new Error("MetaMask chưa được cài đặt.");
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      await updateWalletInfo(accounts[0], provider);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const disconnectWallet = () => {
    setAccount(null);
    setBalance(null);
    setNetwork(null);
    if (onWalletConnected) onWalletConnected(null);
  };

  const shortenAddress = (address) => `${address.slice(0, 6)}...${address.slice(-4)}`;

  const getNetworkDetails = (chainId) => {
    if (!chainId) return { name: 'Đang tải...', color: '#6c757d' };
    const hexId = `0x${Number(chainId).toString(16)}`;
    return NETWORKS[hexId] || { name: `Mạng lạ (ID: ${chainId})`, color: '#6c757d' };
  };

  return (
    <div className="modern-wallet-card">
      <div className="glass-header">
        <div className="brand">
          <span className="brand-dot"></span>
          <h2>Trạng thái ví</h2>
        </div>
        <span className={`status-badge ${isMetaMaskInstalled ? 'success' : 'error'}`}>
          {isMetaMaskInstalled ? 'MetaMask Ready' : 'No MetaMask'}
        </span>
      </div>

      <div className="wallet-body">
        {!account ? (
          <div className="disconnected-view">
            <div className="visual-container">
              <div className="glow-circle"></div>
              <span className="main-emoji">🦊</span>
            </div>
            <h3>Kết nối để bắt đầu</h3>
            <p>Vui lòng kết nối MetaMask để tham gia đấu giá trên Blockchain.</p>
            <button 
              onClick={connectWallet}
              disabled={loading || !isMetaMaskInstalled}
              className="modern-btn primary"
            >
              {loading ? "Đang xử lý..." : "Kết nối Ví"}
            </button>
            {error && <p className="error-text">⚠️ {error}</p>}
          </div>
        ) : (
          <div className="connected-view">
            <div className="bento-grid">
              <div className="bento-item account">
                <span className="label">Địa chỉ ví</span>
                <div className="value-row">
                  <span className="value">{shortenAddress(account)}</span>
                  <button onClick={() => navigator.clipboard.writeText(account)} className="copy-btn-modern">📋</button>
                </div>
              </div>

              <div className="bento-item balance">
                <span className="label">Số dư hiện tại</span>
                <span className="value balance-text">
                  {balance ? parseFloat(balance).toFixed(4) : '0.0000'} <small>ETH</small>
                </span>
              </div>

              <div className="bento-item network">
                <span className="label">Mạng đang dùng</span>
                <div className="current-network-display">
                  <div 
                    className="network-status-pill" 
                    style={{ '--network-color': getNetworkDetails(network?.chainId).color }}
                  >
                    <span className="network-dot"></span>
                    <span className="network-name">{getNetworkDetails(network?.chainId).name}</span>
                  </div>
                </div>
              </div>
            </div>

            <button onClick={disconnectWallet} className="modern-btn outline">
              Ngắt kết nối
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default WalletConnect;
